#!/usr/bin/env python3
"""Street Legends frontend: TV house item (Appliances tab) + house-level schedule player.

PRICE = 5000 (buy), SELL = 2500 (generic half-refund remove endpoint).
User spec (2026-11-03): TV in the Appliances tab; tap the TV inside the
house to play, tap again to stop; the TV plays ON THE CHANNEL SCHEDULE
(not the embed player, which picks the wrong show); NO next/previous
buttons anywhere; playback CONTINUES while a house game modal is open
and CUTS OFF when leaving the house (same as Radio).

SCHEDULE PLAYER (inline WebView HTML, no dependency on the user's TV
app being changed — the TV app is untouched):
- Fetches https://broadcaster.emergent.host/api/schedule/live (public,
  CORS *), finds channel 0c091d20-ef4c-4870-ac55-899a8d1cf947, computes
  Eastern now via Intl.DateTimeFormat timeZone America/New_York, finds
  the slot containing now, and plays that slot's video_url in a <video>
  element, seeking to (now - slot.start_time) on loadedmetadata. It
  recomputes every 15s and on video ended, so it rolls to the next show
  on time. The video is NOT muted: sound plays in the game because the
  WebView sets mediaPlaybackRequiresUserAction={false}.
- If the schedule fetch fails or the channel is absent, it falls back
  to a random show: fetch .../api/channels/<id>, pick a random video
  with a video_url, never repeating the last pick back-to-back;
  re-picks on every fresh turn-on and on video ended in random mode.
- No next/previous buttons exist in this player by design.

SCREEN OVERLAY: when ON, a WebView renders OVER the TV image's screen,
inside the placed-item container (the same View that holds the Image),
at left 16.9%, top 13.4%, width 66.1%, height 61.3% of the item image
(measured screen percentages of the cutout art). Because it lives
inside the item container, it moves/scales with the item exactly like
the image does. The item image is 512x341 (aspect 1.5) and the room
container is 180x120 (aspect 1.5), so resizeMode cover fills the
container exactly and the percentages map to the screen.

LEAVE-HOUSE STOP (three mechanisms, any suffices):
1. useEffect on interiorHouse: when the interior house becomes falsy
   (house closed), stopTv() runs (no-op when not playing).
2. useEffect on interiorHouse items: if the TV is no longer placed
   (sold via any path) while playing, stopTv() runs.
3. TvStopOnUnmount rendered as a sibling just before the LEAVE HOUSE
   button JSX: when the interior modal unmounts, its cleanup stops
   playback. If the LEAVE HOUSE JSX anchor is not matched, a WARNING
   prints and mechanisms 1-2 still cover the close/sell paths.
Game modals open on top of the interior without clearing interiorHouse
and without unmounting the interior modal, so no mechanism fires
while a house game is open — the show keeps playing.

IMAGE: frontend/assets/houses/items/tv.png is written from the
embedded base64 cutout (front-facing TV, transparent background —
house items must be cutouts, never a black square). If the file already
holds the same bytes, SKIP.

SECTIONS (each scoped; a missed anchor prints WARNING and the patch
continues; re-running prints SKIP, never duplicates):
- image write, WebView availability check, appliances entry, imports
  (gated: TV block is only inserted when its required imports actually
  land), TV state + stop/toggle/sell + leave effects, stop-on-unmount
  render, screen overlay inside the placed-item container, itemId tap
  routing, placed-TV guard in handleHouseItemToggle (component scope
  only). The entry + image still land even if the overlay anchor is
  missed (WARNING says so); the toggle then does nothing visible until
  the overlay lands.
- "Already present" checks are scoped to the component being wired
  (never a global check — global checks twice falsely skipped the pool
  and dartboard buttons).

Run from /app: python3 frontend/patch-house-tv-frontend.py
Frontend only: reload Expo Go after running, no build, no Deploy for
this patch itself (the backend catalog patch needs Publish separately).
"""
import base64
import re
import sys
from pathlib import Path

INDEX = Path("frontend/app/(tabs)/index.tsx")
PKG = Path("frontend/package.json")
PNG = Path("frontend/assets/houses/items/tv.png")
MARKER = "TV_FRONTEND_OK"
PRICE = 5000
CHANNEL_ID = "0c091d20-ef4c-4870-ac55-899a8d1cf947"
TV_PNG_B64 = ""
MAP_ANCHOR = "export default function MapScreen() {"
ENTRY = "{ id: 'tv', name: 'TV', image: require('../../assets/houses/items/tv.png'), price: %d }" % PRICE

PLAYER_HTML = """<html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>html,body{margin:0;padding:0;background:#000;height:100%;overflow:hidden}video{width:100%;height:100%;background:#000}</style></head><body><video id="v" playsinline controls></video><script>
var CID='0c091d20-ef4c-4870-ac55-899a8d1cf947';
var SCHED='https://broadcaster.emergent.host/api/schedule/live';
var CHAN='https://broadcaster.emergent.host/api/channels/'+CID;
var v=document.getElementById('v');
var slots=null,mode=null,lastRandom=null,timer=null,curKey=null,errCount=0,errUrl=null;
function esecs(){var p=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',hour:'numeric',minute:'numeric',second:'numeric',hour12:false}).formatToParts(new Date());var g={};for(var i=0;i<p.length;i++){g[p[i].type]=p[i].value;}return (parseInt(g.hour,10)%24)*3600+parseInt(g.minute,10)*60+parseInt(g.second,10);}
function parseT(t){if(typeof t==='number'){return t;}var p=String(t).split(':').map(Number);if(p.length===3){return p[0]*3600+p[1]*60+p[2];}return p[0]*60+p[1];}
function curSlot(){if(!slots){return null;}var now=esecs();for(var i=0;i<slots.length;i++){if(now>=parseT(slots[i].start_time)&&now<parseT(slots[i].end_time)){return {slot:slots[i],index:i,seek:now-parseT(slots[i].start_time)};} }return null;}
function playUrl(url,seek){if(url===errUrl){errCount++;}else{errCount=0;errUrl=url;}v.src=url;v.onloadedmetadata=function(){try{if(seek>0){v.currentTime=seek;}}catch(e){}v.play().catch(function(){});};v.load();}
function playCur(){if(mode==='random'){playRandom();return;}var c=curSlot();if(!c){playRandom();return;}var key=c.slot.video_id+'|'+c.slot.start_time;if(key!==curKey){curKey=key;playUrl(c.slot.video_url,c.seek);}}
function playNextSlot(){var c=curSlot();if(c&&slots[c.index+1]){var nx=slots[c.index+1];curKey=nx.video_id+'|'+nx.start_time;playUrl(nx.video_url,0);}else{playRandom();}}
function playRandom(){fetch(CHAN).then(function(r){return r.json();}).then(function(data){var pool=(data.videos||[]).filter(function(x){return x.video_url;});if(!pool.length){return;}var pick=pool[Math.floor(Math.random()*pool.length)];if(pool.length>1){var guard=0;while(pick.id===lastRandom&&guard<20){pick=pool[Math.floor(Math.random()*pool.length)];guard++;}}lastRandom=pick.id;mode='random';curKey='random|'+pick.id;playUrl(pick.video_url,0);}).catch(function(){});}
v.onended=function(){curKey=null;playCur();};
v.onerror=function(){if(mode==='random'){playRandom();}else if(errCount>=1){playNextSlot();}else{curKey=null;playCur();}};
fetch(SCHED).then(function(r){return r.json();}).then(function(data){var s=(data.schedules||[]).find(function(x){return x.channel_id===CID;});if(!s||!s.videos||!s.videos.length){playRandom();return;}slots=s.videos;mode='schedule';playCur();timer=setInterval(playCur,15000);}).catch(function(){playRandom();});
</script></body></html>"""


def import_after_last(src, line):
    lines = src.split("\n")
    last = -1
    for i, ln in enumerate(lines[:80]):
        if ln.strip().startswith("import "):
            last = i
    if last < 0:
        return src, False
    lines.insert(last + 1, line)
    return "\n".join(lines), True


def add_to_import(src, module, names):
    """Add names to a single-line `import {...} from 'module'`. Returns (src, ok)."""
    m = re.search(r"import\s+(?:\w+\s*,\s*)?\{([^}]*)\}\s*from\s*['\"]" + re.escape(module) + r"['\"]", src)
    if not m:
        return src, False
    have = [x.strip() for x in m.group(1).split(",") if x.strip()]
    missing = [n for n in names if n not in have]
    if not missing:
        return src, True
    new_inner = ", ".join(have + missing)
    src = src[:m.start(1)] + " " + new_inner + " " + src[m.end(1):]
    return src, True


def main():
    try:
        src = INDEX.read_text(encoding="utf-8")
    except FileNotFoundError:
        print("TV_FRONTEND_ERROR: frontend/app/(tabs)/index.tsx not found (run from /app)")
        return 1
    orig = src

    # 0. Image (cutout PNG, embedded base64).
    try:
        png_bytes = base64.b64decode(TV_PNG_B64)
    except Exception as e:
        print("WARNING: TV PNG base64 invalid (%s) - image not written" % e)
        png_bytes = b""
    if png_bytes:
        if PNG.exists() and PNG.read_bytes() == png_bytes:
            print("SKIP: tv.png already present")
        else:
            PNG.parent.mkdir(parents=True, exist_ok=True)
            PNG.write_bytes(png_bytes)
            print("OK: tv.png written (%d bytes)" % len(png_bytes))

    # 1. WebView availability from live package.json (never guess).
    webview_ok = False
    try:
        pkg = PKG.read_text(encoding="utf-8")
        if '"react-native-webview"' in pkg:
            webview_ok = True
    except FileNotFoundError:
        print("WARNING: frontend/package.json not found - WebView availability unknown")
    if not webview_ok:
        print("WARNING: react-native-webview not in package.json - TV wiring SKIPPED (entry + image still land)")

    # 2. HOUSE_ITEMS appliances entry (scoped to the HOUSE_ITEMS block).
    if ENTRY in src:
        print("SKIP: TV already in Appliances list")
    else:
        hpos = src.find("HOUSE_ITEMS")
        ok = False
        if hpos >= 0:
            apos = src.find("appliances:", hpos)
            if apos >= 0:
                bstart = src.find("[", apos)
                if bstart >= 0:
                    depth = 0
                    bend = -1
                    for i in range(bstart, min(len(src), bstart + 8000)):
                        c = src[i]
                        if c == "[":
                            depth += 1
                        elif c == "]":
                            depth -= 1
                            if depth == 0:
                                bend = i
                                break
                    if bend > bstart:
                        inner = src[bstart + 1:bend]
                        if inner.strip() == "":
                            src = src[:bend] + ENTRY + src[bend:]
                        else:
                            src = src[:bend] + ", " + ENTRY + src[bend:]
                        print("OK: TV added to Appliances list")
                        ok = True
        if not ok:
            print("WARNING: HOUSE_ITEMS appliances array anchor not matched - TV not added to menu")

    # 3. Imports + module block + TV state (gated: only insert code whose imports landed).
    tv_ok = False
    if webview_ok and "toggleTv" not in src:
        if MAP_ANCHOR not in src:
            print("WARNING: MapScreen anchor not found - TV block not added")
        else:
            work = src
            imp_ok = True
            work, ok = add_to_import(work, "react", ["useState", "useCallback", "useEffect"])
            if not ok:
                print("WARNING: could not extend react import (useState/useCallback/useEffect)")
                imp_ok = False
            work, ok = add_to_import(work, "react-native", ["Alert"])
            if not ok:
                print("WARNING: could not extend react-native import (Alert)")
                imp_ok = False
            if "from 'react-native-webview'" in work or 'from "react-native-webview"' in work:
                print("SKIP: react-native-webview import already present")
            else:
                work, ok = import_after_last(work, "import { WebView } from 'react-native-webview';")
                if not ok or "WebView" not in work:
                    print("WARNING: could not add react-native-webview import")
                    imp_ok = False
                else:
                    print("OK: react-native-webview import added")
            if imp_ok:
                if "TV_SCHEDULE_PLAYER_HTML" not in work:
                    module_block = """
// TV_SCHEDULE: house-level TV controller. Rendered inside the house
// interior only; unmounting stops playback (LEAVE HOUSE safety net).
const TvStopOnUnmount = ({ onStop }: { onStop: () => void }) => {
  useEffect(() => {
    return () => { onStop(); };
  }, []);
  return null;
};

const TV_SCHEDULE_PLAYER_HTML = `""" + PLAYER_HTML + """`;
"""
                    work = work.replace(MAP_ANCHOR, module_block.strip("\n") + "\n\n" + MAP_ANCHOR, 1)
                    print("OK: TV stop-on-unmount component + schedule player HTML added")
                state_block = """
  // TV_SCHEDULE (house-level): owned by the interior, NOT by any game
  // modal, so opening a house game never stops it. LEAVE HOUSE stops it
  // via the interiorHouse effects below + TvStopOnUnmount cleanup.
  // Re-entering the house leaves the TV OFF (tvOn is only set by
  // tapping the TV, never restored on enter).
  const [tvOn, setTvOn] = useState(false);
  const stopTv = useCallback(() => { setTvOn(false); }, []);
  const toggleTv = useCallback(() => { setTvOn((p: boolean) => !p); }, []);
  const sellTv = async () => {
    stopTv();
    if (!interiorHouse || !playerId) return;
    try {
      const res = await removeHouseItem(interiorHouse.id, playerId, 'tv');
      if (res?.house) {
        setInteriorHouse(res.house);
      } else {
        setInteriorHouse({ ...interiorHouse, items: (interiorHouse.items || []).filter((it: any) => it.item_id !== 'tv') });
      }
      if (res && typeof res.cash === 'number' && player) setPlayer({ ...player, cash: res.cash });
    } catch (e: any) {
      Alert.alert('Could not sell', e?.message || 'Try again.');
    }
  };
  useEffect(() => {
    if (!interiorHouse) { stopTv(); }
  }, [interiorHouse, stopTv]);
  useEffect(() => {
    if (tvOn && interiorHouse && !(interiorHouse.items || []).some((it: any) => it.item_id === 'tv')) { stopTv(); }
  }, [interiorHouse, tvOn, stopTv]);
"""
                work = work.replace(MAP_ANCHOR, MAP_ANCHOR + state_block.rstrip("\n"), 1)
                src = work
                tv_ok = True
                print("OK: TV state + stop/toggle/sell + leave effects added")
            else:
                print("WARNING: TV block skipped (imports missing) - code would reference missing imports")
    elif "toggleTv" in src:
        print("SKIP: TV state already present")
        tv_ok = True

    # 4a. Stop-on-unmount render just before the LEAVE HOUSE button.
    if tv_ok and "TvStopOnUnmount onStop" not in src:
        lines = src.split("\n")
        # The real button is a <Text>LEAVE HOUSE</Text> line; ignore comment
        # mentions of LEAVE HOUSE (the patch's own comments contain it).
        cands = [i for i, ln in enumerate(lines) if "LEAVE HOUSE" in ln]
        text_cands = [i for i in cands if "<Text" in lines[i]]
        leave_idx = text_cands[0] if text_cands else (cands[-1] if cands else -1)
        placed = False
        if leave_idx >= 0:
            for j in range(leave_idx, max(-1, leave_idx - 8), -1):
                if "TouchableOpacity" in lines[j]:
                    indent = lines[j][:len(lines[j]) - len(lines[j].lstrip())]
                    lines.insert(j, indent + "{tvOn ? (<TvStopOnUnmount onStop={stopTv} />) : null}")
                    src = "\n".join(lines)
                    placed = True
                    print("OK: stop-on-unmount render added before LEAVE HOUSE button")
                    break
        if not placed:
            print("WARNING: LEAVE HOUSE button anchor not matched - stop-on-unmount render not added (interiorHouse effects still stop on close/sell)")
    elif "TvStopOnUnmount onStop" in src:
        print("SKIP: stop-on-unmount render already present")

    # 4b. Screen overlay inside the placed-item container (moves with the item).
    if tv_ok and "TV_SCHEDULE_OVERLAY" not in src:
        mappos = src.find("interiorHouse?.items")
        over = None
        if mappos >= 0:
            m = re.search(r"<Image\s+source=\{def\.image\}[\s\S]{0,500}?(?:/>|</Image>)", src[mappos:])
            if m:
                img_start = mappos + m.start()
                img_end = mappos + m.end()
                overlay = """{/* TV_SCHEDULE_OVERLAY */}
{placed.item_id === 'tv' && tvOn ? (
  <View style={{ position: 'absolute', left: '16.9%', top: '13.4%', width: '66.1%', height: '61.3%', backgroundColor: '#000', borderRadius: 4, overflow: 'hidden' }}>
    <WebView source={{ html: TV_SCHEDULE_PLAYER_HTML }} mediaPlaybackRequiresUserAction={false} allowsInlineMediaPlayback={true} javaScriptEnabled={true} originWhitelist={['*']} style={{ flex: 1, backgroundColor: '#000' }} />
  </View>
) : null}"""
                src = src[:img_start] + "<>" + src[img_start:img_end] + "\n" + overlay + "\n</>" + src[img_end:]
                over = True
                print("OK: TV screen overlay added inside placed-item container (16.9%/13.4%/66.1%/61.3%)")
        if not over:
            print("WARNING: placed-item image anchor (def.image in the interiorHouse items map) not matched - TV screen overlay NOT wired (entry + image still land; tapping the TV toggles tvOn but shows no video until the overlay lands)")
    elif "TV_SCHEDULE_OVERLAY" in src:
        print("SKIP: TV screen overlay already present")

    # 5. ItemId tap routing: tapping the placed TV toggles it (same router games use).
    if "=== 'tv') toggleTv" in src or '=== "tv") toggleTv' in src:
        print("SKIP: TV tap already wired")
    elif tv_ok:
        tap_pat = re.compile(
            r"^([ \t]*)if\s*\(\s*(\w+)\s*===\s*'(scrabble|texas_holdem|dominoes|cardtable|dartboard|pool-table|chess_checkers|radio)'\s*\)\s*set\w+MenuOpen\(true\);",
            re.M,
        )
        m = tap_pat.search(src)
        if m:
            indent, var = m.group(1), m.group(2)
            src = src[:m.end()] + "\n" + indent + "if (%s === 'tv') toggleTv();" % var + src[m.end():]
            print("OK: TV tap wired (after %s router line)" % m.group(3))
        else:
            print("WARNING: item tap router anchor not found - TV tap not wired")

    # 6. Placed-TV guard in handleHouseItemToggle (component scope only).
    if "toggleTv(); return; }" in src and "id === 'tv'" in src:
        print("SKIP: handleHouseItemToggle TV guard already present")
    elif tv_ok:
        mappos = src.find(MAP_ANCHOR)
        hpos = src.find("handleHouseItemToggle")
        done = False
        if mappos >= 0 and hpos > mappos:
            dm = re.search(r"handleHouseItemToggle\s*=\s*(?:async\s*)?\(\s*(\w+)", src[hpos:])
            if dm:
                param = dm.group(1)
                bpos = src.find("{", hpos + dm.end())
                if bpos >= 0 and bpos - hpos < 200:
                    indent = "      "
                    guard = "\n" + indent + "if (%s?.id === 'tv' && (interiorHouse?.items || []).some((it: any) => it.item_id === 'tv')) { toggleTv(); return; }" % param
                    src = src[:bpos + 1] + guard + src[bpos + 1:]
                    print("OK: placed-TV guard added to handleHouseItemToggle")
                    done = True
        if not done:
            print("WARNING: handleHouseItemToggle anchor not matched - menu-row guard not added (item tap router may still cover it)")

    if src != orig:
        INDEX.write_text(src, encoding="utf-8")
        print("OK: index.tsx updated")
    else:
        print("SKIP: index.tsx unchanged")
    print(MARKER)
    return 0


if __name__ == "__main__":
    sys.exit(main())
